607	public enum AddressStatus {
608	    PENDING {
609	        @Override
610	        public boolean canTransitionTo(AddressStatus nextStatus) {
611	            return nextStatus == SHIPPED || nextStatus == CANCELED;
612	        }
613	    },
614	    SHIPPED {
615	        @Override
616	        public boolean canTransitionTo(AddressStatus nextStatus) {
617	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
618	        }
619	    },
620	    IN_TRANSIT {
621	        @Override
622	        public boolean canTransitionTo(AddressStatus nextStatus) {
623	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
624	                    || nextStatus == DELIVERED;
625	        }
626	    },
627	    OUT_FOR_DELIVERY {
628	        @Override
629	        public boolean canTransitionTo(AddressStatus nextStatus) {
630	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
631	        }
632	    },
633	    DELIVERED {
634	        @Override
635	        public boolean canTransitionTo(AddressStatus nextStatus) {
636	            return false;
637	        }
638	    },
639	    RETURNED {
640	        @Override
641	        public boolean canTransitionTo(AddressStatus nextStatus) {
642	            return nextStatus == CANCELED;
643	        }
644	    },
645	    CANCELED {
646	        @Override
647	        public boolean canTransitionTo(AddressStatus nextStatus) {
648	            return false;
649	        }
650	    },
651	    DELAYED {
652	        @Override
653	        public boolean canTransitionTo(AddressStatus nextStatus) {
654	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
655	        }
656	    },
657	    FAILED_DELIVERY {
658	        @Override
659	        public boolean canTransitionTo(AddressStatus nextStatus) {
660	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
661	        }
662	    };
663	
664	    public abstract boolean canTransitionTo(AddressStatus nextStatus);
665	}
