238	            if (order == null) {
239	                return false;
240	            }
243	            FaqStatus currentStatus = order.getStatus();
244	            return currentStatus != FaqStatus.PENDING_PAYMENT;
246	        } catch (Exception e) {
247	            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
