private void notifyUsersAndUpdateSaleStatus(Faq order, Notification payment) {
    try {
        log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
        FaqBid orderBid = order.getOrderBid();
        if (orderBid == null) {
            StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
            if (saleBid == null) {
                log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
                return;
            }
            Style sale = saleBid.getSale();
            if (sale == null) {
                log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
                return;
            }
            sendNotifications(order, sale);
            sale.updateStatus(StyleStatus.SOLD);
            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
            return;
        }
        Style sale = orderBid.getSale();
        if (sale == null) {
            log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
            return;
        }
        sendNotifications(order, sale);
        sale.updateStatus(StyleStatus.SOLD);
        log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
    } catch (Exception e) {
        log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
                order.getId(), e.getMessage(), e);
    }
}
private void sendNotifications(Faq order, Style sale) {
    try {
        Product buyer = order.getUser();
        if (buyer != null) {
            notificationCommandService.createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "결제가 완료되었습니다. 주문 ID: " + order.getId()
            );
            log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
        }
        Product seller = sale.getSeller();
        if (seller != null) {
            notificationCommandService.createNotification(
                    seller.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
            );
            log.debug("판매자 알림 전송 완료: 판매자ID={}", seller.getId());
        }
    } catch (Exception e) {
        log.warn("결제 완료 알림 전송 중 오류 발생: 주문ID={}, 판매ID={}, 오류={}",
                order.getId(), sale.getId(), e.getMessage());
    }
}

