                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
            );
            log.debug("판매자 알림 전송 완료: 판매자ID={}", seller.getId());
        }
    } catch (Exception e) {
        log.warn("결제 완료 알림 전송 중 오류 발생: 주문ID={}, 판매ID={}, 오류={}",
                order.getId(), sale.getId(), e.getMessage());
    }
}

